{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "To be included in this review, studies had to explore facilitators and/or barriers to PA in older patients during hospitalization. Studies were included if: 1) they were published between January 1, 2000, and May 29, 2021; 2) they were written in English, German, or Dutch; 3) they used a quantitative, qualitative, or mixed-methods study design; and 4) the study population consisted of patients aged ≥ 65 years (baseline mean age of 65 years or older), caregivers, or HCPs.",
      "reason": "Specifies study designs, settings, population, and time frame, but follow-up requirements are not mentioned."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "studies were included if: 1) they were published between January 1, 2000, and May 29, 2021; 2) they were written in English, German, or Dutch; ... Studies were excluded if they were: 1) editorials, opinion papers, conference abstracts, or literature reviews; ...",
      "reason": "Eligibility criteria for report characteristics including dissemination year, language, and publication status are specified."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The evidence does not indicate that exclusion was based on outcomes not measured versus not reported; such distinction is not made in the eligibility criteria."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "The level of evidence of facilitators and/or barriers from quantitative studies and quantitative parts of mixedmethods studies was assessed using the best evidence synthesis approach [40, 41]. The approach was applied to facilitators and barriers that were reported at least once in RCTs or at least twice in non-randomized studies. ... Subsequently, the overall quality scores of each study were used to group studies into two categories: high (MMAT score 4 or 5) and low (MMAT score 0-3) quality.",
      "reason": "Groups used in synthesis (based on study design and quality) are specified and linked to the evidence synthesis approach, which relates to the review's objective of identifying facilitators and barriers."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "Given the specific hospital setting in the current review, in which patients enter a different and unfamiliar context, it is conceivable that facilitators and barriers might be different for patients over 65 years than for younger patients.",
      "reason": "Rationale is provided for focusing on older patients and hospital setting, but not for other restrictions like language or publication year."
    }
  ],
  "confidence": 85
}

